def agree(entries,eps):
    vals=sorted(set(v for v,w in entries if w>0))
    best=None;bestint=None
    for lo in vals:
        for hi in vals:
            if hi<lo:continue
            if PPM*(hi-lo)<=eps*hi:
                w=sum(wt for v,wt in entries if wt>0 and lo<=v<=hi)
                cand=(w,-lo,-hi)
                if best is None or cand>best:
                    best=cand;bestint=(lo,hi)
    w,_,_=best;lo,hi=bestint
    mass=sum(wt for v,wt in entries if wt>0 and lo<=v<=hi)
    s=sum(v*wt for v,wt in entries if wt>0 and lo<=v<=hi)
    return s//mass,mass

